select id, dept_name, rank() over w_recent as budget_rank, percent_rank() over (partition by location order by budget desc nulls last) as budget_percent_rank, row_number() over (partition by dept_name, location order by budget asc, id asc) as seq_no, last_value(dept_name) ignore nulls over (order by budget asc, id asc rows between unbounded preceding and current row) as last_known_dept_name from departments where budget between 1110000 and 1872000 window w_recent as (order by budget asc nulls first);
